class SourceCache:
    """
    A class that caches source code snippets for use in dev commands.
    This allows for proper error tracebacks when code spans multiple snippets.
    """
    def __init__(self) -> None:
        self._cache: Dict[str, str] = {}
        self._next_index = 0

    def take_next_index(self) -> int:
        """Get the next available index for a new source snippet."""
        index = self._next_index
        self._next_index += 1
        return index

    def store(self, filename: str, source: str) -> None:
        """Store a source snippet with the given filename."""
        self._cache[filename] = source

    def get(self, filename: str) -> str:
        """Get a source snippet by filename."""
        return self._cache.get(filename, "")


